contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests calling C.transfer with arbitrary inputs
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty _tos as C.transfer requires it
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert then it must return true (per implementation)
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

